namespace config {
    static const char* UPLOAD_DIR = "/tmp/k8s-api-uploads";
    static const mode_t DIR_PERMS = 0750;
    static const size_t MAX_UPLOAD_SIZE = 10 * 1024 * 1024;
    static const int CLEANUP_INTERVAL_SEC = 300;
}

class SecureTempFile {
private:
    std::string path_;
    int fd_;
    bool committed_;

    static std::string generate_unique_suffix() {
        unsigned char buf[16];
        int urandom = open("/dev/urandom", O_RDONLY);
        if (urandom < 0) {
            // Fallback: use pid + timestamp for entropy
            snprintf(reinterpret_cast<char*>(buf), sizeof(buf),
                     "%08x%04x", static_cast<unsigned>(time(nullptr)),
                     static_cast<unsigned>(getpid() & 0xFFFF));
            return std::string(reinterpret_cast<char*>(buf), 12);
        }
        read(urandom, buf, sizeof(buf));
        close(urandom);
        char hex[33];
        for (int i = 0; i < 16; i++)
            snprintf(hex + i*2, 3, "%02x", buf[i]);
        return std::string(hex, 32);
    }

public:
    SecureTempFile(const std::string& prefix) : fd_(-1), committed_(false) {
        ensure_upload_dir();
        std::string tmpl = std::string(config::UPLOAD_DIR) + "/" + prefix + "_XXXXXX";
        char* tmpl_buf = strdup(tmpl.c_str());
        fd_ = mkstemp(tmpl_buf);
        if (fd_ >= 0) {
            path_ = tmpl_buf;
            // Set restrictive permissions
            fchmod(fd_, 0600);
        }
        free(tmpl_buf);
    }

    ~SecureTempFile() {
        if (fd_ >= 0) close(fd_);
        if (!committed_ && !path_.empty()) {
            unlink(path_.c_str());
        }
    }

    static void ensure_upload_dir() {
        struct stat st;
        if (stat(config::UPLOAD_DIR, &st) != 0) {
            mkdir(config::UPLOAD_DIR, config::DIR_PERMS);
        }
    }

    int fd() const { return fd_; }
    const std::string& path() const { return path_; }
    void commit() { committed_ = true; }

    ssize_t write_data(const char* data, size_t len) {
        if (fd_ < 0) return -1;
        return write(fd_, data, len);
    }
};

class RequestProcessor {
private:
    std::string request_id_;
    std::string staging_path_;

    std::string compute_staging_path(const std::string& filename) {
        // Sanitize filename - remove path separators
        std::string safe_name;
        for (char c : filename) {
            if (c != '/' && c != '\\' && c != '\0')
                safe_name += c;
        }
        if (safe_name.empty()) safe_name = "unnamed";
        return std::string(config::UPLOAD_DIR) + "/staging_" + request_id_ + "_" + safe_name;
    }

public:
    RequestProcessor(const std::string& req_id) : request_id_(req_id) {}

    int stage_upload(const char* data, size_t size, const std::string& filename) {
        staging_path_ = compute_staging_path(filename);

        // Create staging file with unique name derived from request context
        // Using O_CREAT|O_EXCL for atomic creation
        int fd = open(staging_path_.c_str(), O_WRONLY | O_CREAT | O_TRUNC, 0600);
        if (fd < 0) {
            return -1;
        }

        ssize_t written = write(fd, data, size);
        close(fd);

        if (written != static_cast<ssize_t>(size)) {
            unlink(staging_path_.c_str());
            return -1;
        }
        return 0;
    }

    int finalize(const std::string& dest_dir) {
        std::string final_path = dest_dir + "/" + request_id_;
        if (rename(staging_path_.c_str(), final_path.c_str()) != 0) {
            unlink(staging_path_.c_str());
            return -1;
        }
        return 0;
    }

    void cleanup() {
        if (!staging_path_.empty())
            unlink(staging_path_.c_str());
    }
};

static int handle_upload(void* cls, struct MHD_Connection* connection,
                         const char* url, const char* method,
                         const char* version, const char* upload_data,
                         size_t* upload_data_size, void** con_cls) {
    if (strcmp(method, "POST") != 0) {
        const char* err = "Method not allowed";
        struct MHD_Response* resp = MHD_create_response_from_buffer(
            strlen(err), (void*)err, MHD_RESPMEM_PERSISTENT);
        int ret = MHD_queue_response(connection, MHD_HTTP_METHOD_NOT_ALLOWED, resp);
        MHD_destroy_response(resp);
        return ret;
    }

    // Generate request ID from connection metadata
    char req_id[64];
    snprintf(req_id, sizeof(req_id), "req_%lu_%d",
             static_cast<unsigned long>(time(nullptr)), getpid());

    if (*upload_data_size > 0 && *upload_data_size <= config::MAX_UPLOAD_SIZE) {
        RequestProcessor proc(req_id);
        const char* fname = MHD_lookup_connection_value(
            connection, MHD_GET_ARGUMENT_KIND, "filename");
        std::string filename = fname ? fname : "upload.bin";

        if (proc.stage_upload(upload_data, *upload_data_size, filename) == 0) {
            proc.finalize("/var/data/uploads");
        } else {
            proc.cleanup();
        }
        *upload_data_size = 0;
    }

    const char* ok = "{\"status\": \"accepted\"}";
    struct MHD_Response* resp = MHD_create_response_from_buffer(
        strlen(ok), (void*)ok, MHD_RESPMEM_PERSISTENT);
    MHD_add_response_header(resp, "Content-Type", "application/json");
    int ret = MHD_queue_response(connection, MHD_HTTP_OK, resp);
    MHD_destroy_response(resp);
    return ret;
}

int main(int argc, char** argv) {
    SecureTempFile::ensure_upload_dir();

    struct MHD_Daemon* daemon = MHD_start_daemon(
        MHD_USE_THREAD_PER_CONNECTION,
        8080, nullptr, nullptr,
        &handle_upload, nullptr,
        MHD_OPTION_END);

    if (!daemon) {
        fprintf(stderr, "Failed to start HTTP daemon\n");
        return 1;
    }

    printf("API server listening on :8080\n");
    pause();
    MHD_stop_daemon(daemon);
    return 0;
}
